Tier[] zoo = { new Hund(), new Katze(), new Fisch() };

foreach (Tier t in zoo)
{
    t.Laut();
}
// Ausgabe:
// Wuff!
// Miau!
// ...

class Tier
{
    public virtual void Laut()
    {
        Console.WriteLine("...");
    }
}

class Hund : Tier
{
    public override void Laut()
    {
        Console.WriteLine("Wuff!");
    }
}

class Katze : Tier
{
    public override void Laut()
    {
        Console.WriteLine("Miau!");
    }
}

class Fisch : Tier
{
    // kein override – der Fisch verwendet die Standard-Version
}

Mitarbeiter m = new Mitarbeiter("Eva", 2000);
Mitarbeiter c = new Chef("Karl", 3000);

Console.WriteLine($"{m.Name}: {m.Gehalt()} Euro");
Console.WriteLine($"{c.Name}: {c.Gehalt()} Euro");
// Ausgabe:
// Eva: 2000 Euro
// Karl: 3500 Euro

class Mitarbeiter
{
    public string Name { get; }
    protected int grundgehalt;

    public Mitarbeiter(string name, int grundgehalt)
    {
        Name = name;
        this.grundgehalt = grundgehalt;
    }

    public virtual int Gehalt()
    {
        return grundgehalt;
    }
}

class Chef : Mitarbeiter
{
    public Chef(string name, int grundgehalt) : base(name, grundgehalt) { }

    public override int Gehalt()
    {
        return base.Gehalt() + 500;   // Original plus Zulage
    }
}

Punkt p = new Punkt(3, 7);
Console.WriteLine(p);
Console.WriteLine($"Start bei {p}");
// Ausgabe:
// (3|7)
// Start bei (3|7)

class Punkt
{
    public int X { get; }
    public int Y { get; }

    public Punkt(int x, int y)
    {
        X = x;
        Y = y;
    }

    public override string ToString()
    {
        return $"({X}|{Y})";
    }
}

Tier t = new Kuh();
t.Laut();
// Ausgabe: ...
// (nicht Muh! – Kuh.Laut() ist kein override)

class Tier
{
    public virtual void Laut()
    {
        Console.WriteLine("...");
    }
}

class Kuh : Tier
{
    public void Laut()   // Warnung: verbirgt Tier.Laut()
    {
        Console.WriteLine("Muh!");
    }
}

