Fahrzeug f = new Auto();
Console.WriteLine(f.Beschreibung());

class Fahrzeug
{
    public virtual string Beschreibung() => "Fahrzeug";
}

class Auto : Fahrzeug
{
    public override string Beschreibung() => "Auto";
}

Aufgabe a = new Bonus();
Console.WriteLine(a.Punkte());

class Aufgabe
{
    public virtual int Punkte() => 10;
}

class Bonus : Aufgabe
{
    public override int Punkte() => base.Punkte() * 2;
}

