Schueler s = new Schueler("Lena", 2);
Console.WriteLine(s);

class Schueler
{
    private string name;
    private int note;

    public Schueler(string name, int note)
    {
        this.name = name;
        this.note = note;
    }

    public override string ToString() => $"{name} ({note})";
}
